def bidang_singgung(f, x0, y0, x, y):
    h = 1e-6
    fx = (f(x0 + h, y0) - f(x0 - h, y0)) / (2 * h)
    fy = (f(x0, y0 + h) - f(x0, y0 - h)) / (2 * h)
    return round(f(x0, y0) + fx * (x - x0) + fy * (y - y0), 4)

