def turun_gradien(grad, mulai, lr, langkah):
    p = [float(v) for v in mulai]
    for _ in range(langkah):
        g = grad(p)
        p = [a - lr * b for a, b in zip(p, g)]
    return [round(v, 4) + 0.0 for v in p]

