def gradien_mse(w, b, x, y):
    n = len(x)
    galat = [w * a + b - t for a, t in zip(x, y)]
    dw = 2 * sum(e * a for e, a in zip(galat, x)) / n
    db = 2 * sum(galat) / n
    return (round(dw, 4) + 0.0, round(db, 4) + 0.0)

