exercises.solution:
def fit_gd(x, y, lr, langkah):
    n = len(x)
    w, b = 0.0, 0.0
    for _ in range(langkah):
        galat = [w * a + b - t for a, t in zip(x, y)]
        dw = 2 * sum(e * a for e, a in zip(galat, x)) / n
        db = 2 * sum(galat) / n
        w -= lr * dw
        b -= lr * db
    return (round(w, 3) + 0.0, round(b, 3) + 0.0)
